messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
    </style>
</head>
<body>
    <!-- Import Map to load Three.js from a CDN as an ES Module -->
    <script type="importmap">
        {
            "imports": {
                "three": "https://unpkg.com/three@0.160.0/build/three.module.js"
            }
        }
    </script>

    <script type="module">
        import * as THREE from 'three';

        // --- Configuration ---
        const TRACK_LENGTH = 100;
        const FINISH_LINE_Z = -TRACK_LENGTH;
        const CAR_WIDTH = 2.2;
        const CAR_HEIGHT = 1.2;
        const CAR_LENGTH = 4.5;

        // --- Setup Scene, Camera, Renderer ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 120);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 200);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(10, 20, 10);
        dirLight.castShadow = true;
        dirLight.shadow.camera.top = 20;
        dirLight.shadow.camera.bottom = -20;
        dirLight.shadow.camera.left = -20;
        dirLight.shadow.camera.right = 20;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // --- Environment (Ground & Track) ---

        // Ground Plane
        const groundGeo = new THREE.PlaneGeometry(200, 300);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x3b7d3b });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.1;
        ground.position.z = -50;
        ground.receiveShadow = true;
        scene.add(ground);

        // Track Surface
        const trackGeo = new THREE.PlaneGeometry(12, 120);
        const trackMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const track = new THREE.Mesh(trackGeo, trackMat);
        track.rotation.x = -Math.PI / 2;
        track.position.y = 0;
        track.position.z = -50;
        track.receiveShadow = true;
        scene.add(track);

        // Finish Line (Zebra stripes)
        const finishGroup = new THREE.Group();

        // Create a canvas texture for the checkered pattern
        const canvas = document.createElement('canvas');
        canvas.width = 64;
        canvas.height = 64;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0,0,64,64);
        ctx.fillStyle = '#000000';
        ctx.fillRect(0,0,32,32);
        ctx.fillRect(32,32,32,32);

        const finishTexture = new THREE.CanvasTexture(canvas);
        finishTexture.wrapS = THREE.RepeatWrapping;
        finishTexture.wrapT = THREE.RepeatWrapping;
        finishTexture.repeat.set(4, 2); // Repeat to cover the track width

        const finishGeo = new THREE.PlaneGeometry(12, 2);
        const finishMat = new THREE.MeshStandardMaterial({ map: finishTexture });
        const finishLine = new THREE.Mesh(finishGeo, finishMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.01, FINISH_LINE_Z); // Just above track
        finishGroup.add(finishLine);

        // Finish Line Posts
        const postGeo = new THREE.BoxGeometry(0.5, 5, 0.5);
        const postMat = new THREE.MeshStandardMaterial({ color: 0x555555 });
        const postL = new THREE.Mesh(postGeo, postMat);
        postL.position.set(-6, 2.5, FINISH_LINE_Z);
        finishGroup.add(postL);
        const postR = new THREE.Mesh(postGeo, postMat);
        postR.position.set(6, 2.5, FINISH_LINE_Z);
        finishGroup.add(postR);

        scene.add(finishGroup);


        // --- Car Creation ---
        function createCar(colorHex) {
            const carGroup = new THREE.Group();

            // Materials
            const bodyMat = new THREE.MeshStandardMaterial({ color: colorHex, roughness: 0.3, metalness: 0.4 });
            const glassMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.1, metalness: 0.8 });
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

            // Chassis (Main Body)
            const chassisGeo = new THREE.BoxGeometry(CAR_WIDTH, 0.8, CAR_LENGTH);
            const chassis = new THREE.Mesh(chassisGeo, bodyMat);
            chassis.position.y = 0.6;
            chassis.castShadow = true;
            chassis.receiveShadow = true;
            carGroup.add(chassis);

            // Cabin (Top)
            const cabinGeo = new THREE.BoxGeometry(CAR_WIDTH - 0.4, 0.6, CAR_LENGTH * 0.5);
            const cabin = new THREE.Mesh(cabinGeo, glassMat);
            cabin.position.y = 1.3;
            cabin.position.z = -0.2;
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.3, 16);
            wheelGeo.rotateZ(Math.PI / 2);

            const wheelPositions = [
                { x: -CAR_WIDTH/2, z: 1.2 },
                { x: CAR_WIDTH/2, z: 1.2 },
                { x: -CAR_WIDTH/2, z: -1.2 },
                { x: CAR_WIDTH/2, z: -1.2 }
            ];

            wheelPositions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.position.set(pos.x, 0.4, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            // Spoiler (Racing detail)
            const spoilerGeo = new THREE.BoxGeometry(CAR_WIDTH + 0.2, 0.1, 0.5);
            const spoiler = new THREE.Mesh(spoilerGeo, bodyMat);
            spoiler.position.set(0, 1.3, -CAR_LENGTH/2 + 0.2);
            carGroup.add(spoiler);

            // Spoiler legs
            const legGeo = new THREE.BoxGeometry(0.2, 0.3, 0.2);
            const legL = new THREE.Mesh(legGeo, bodyMat);
            legL.position.set(-0.8, 1.1, -CAR_LENGTH/2 + 0.2);
            carGroup.add(legL);
            const legR = new THREE.Mesh(legGeo, bodyMat);
            legR.position.set(0.8, 1.1, -CAR_LENGTH/2 + 0.2);
            carGroup.add(legR);

            return carGroup;
        }

        // Create Cars
        const blueCar = createCar(0x0000FF); // Blue
        const redCar = createCar(0xFF0000); // Red

        // Initial Positions
        blueCar.position.set(-3, 0, 0); // Left lane
        redCar.position.set(3, 0, 0);   // Right lane

        scene.add(blueCar);
        scene.add(redCar);

        // --- Animation State ---
        let raceTime = 0;
        let lastTime = 0;

        // Physics State
        let bluePos = 0;
        let redPos = 0;

        let blueSpeed = 0;
        let redSpeed = 0;

        // 0 = Start, 1 = Finished (Red wins)
        let racePhase = 0; 

        // Reset Logic
        function resetRace() {
            bluePos = 0;
            redPos = 0;
            blueSpeed = 0;
            redSpeed = 0;
            racePhase = 0;
            raceTime = 0;
        }

        // --- Main Loop ---
        function animate(time) {
            requestAnimationFrame(animate);

            const dt = (time - lastTime) / 1000; // Delta time in seconds
            lastTime = time;

            // Cap dt to prevent huge jumps if tab is inactive
            if (isNaN(dt) || dt > 0.1) return;

            // --- Logic ---
            if (racePhase === 0) {
                raceTime += dt;

                // Blue Car Logic: Starts fast, slows down slightly, maintains steady
                // Speed profile: High start, gentle deceleration to cruising
                if (raceTime < 2.0) {
                    blueSpeed = 35 + (raceTime * 5); // Accelerate
                } else {
                    blueSpeed = 45; // Cruising
                }

                // Red Car Logic: Slow start, massive acceleration, overtakes
                // Speed profile: Low start, exponential acceleration
                if (raceTime < 1.5) {
                    redSpeed = 10 + (raceTime * 5); // Slow start
                } else if (raceTime < 5.0) {
                    // Aggressive acceleration
                    redSpeed += 12 * dt; 
                } else {
                    redSpeed = 65; // Top speed
                }

                // Update Positions
                bluePos += blueSpeed * dt;
                redPos += redSpeed * dt;

                // Check Finish Line
                if (redPos >= TRACK_LENGTH || bluePos >= TRACK_LENGTH) {
                    racePhase = 1; // Race Over
                }
            } else {
                // --- Post Race / Reset Logic ---

                // Move cars past finish line for visual clarity
                bluePos += 20 * dt;
                redPos += 20 * dt;

                // Camera Reset Animation
                // We will let the camera follow the cars but smooth it out

                // Wait until cars are well past the finish line, then reset
                if (redPos > TRACK_LENGTH + 20) {
                    resetRace();
                }
            }

            // Update Car Meshes
            blueCar.position.z = -bluePos;
            redCar.position.z = -redPos;

            // Wheel rotation visual (simple approximation)
            const wheelRotSpeed = 10;
            blueCar.children.forEach(child => {
                if (child.geometry.type === 'CylinderGeometry') {
                    child.rotation.x += blueSpeed * dt * wheelRotSpeed;
                }
            });
            redCar.children.forEach(child => {
                if (child.geometry.type === 'CylinderGeometry') {
                    child.rotation.x += redSpeed * dt * wheelRotSpeed;
                }
            });


            // --- Camera Logic ---
            // Target position is roughly halfway between cars, slightly ahead, high angle
            const leadCarZ = Math.min(bluePos, redPos); // Most negative Z (furthest down track)
            const leadCarX = (leadCarZ === bluePos) ? blueCar.position.x : redCar.position.x;

            // Look at point: slightly ahead of the leading car
            const lookAtZ = leadCarZ - 15;
            const lookAtX = 0; // Center of track

            const camX = 15; // Offset to the right to see both lanes
            const camY = 12;
            const camZ = leadCarZ + 25; // Behind the leader

            // Smoothly interpolate camera position
            camera.position.lerp(new THREE.Vector3(camX, camY, camZ), 0.05);

            const targetLookAt = new THREE.Vector3(lookAtX, 1, lookAtZ);
            camera.lookAt(targetLookAt);

            renderer.render(scene, camera);
        }

        // Handle Window Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start Loop
        requestAnimationFrame(animate);

    </script>
</body>
</html>
```
